constexpr std::size_t kAliceCertSigField = 87; // 4-byte length + the 83-byte ed25519 signature

std::string str(std::string_view s) {
    std::string out;
    detail::put_string(out, s);
    return out;
}
std::string mp(std::string_view magnitude) {
    std::string out;
    detail::put_mpint(out, magnitude);
    return out;
}
std::string b64(std::string_view bytes) { return yuzu::shared::base64_encode(bytes, true); }
std::string unb64(const std::string& s) { return *yuzu::shared::base64_decode(s); }

/// A single-key file's text and what parse_authorized_keys made of it.
struct Parsed {
    KeysParse kp;
    std::vector<std::vector<std::string>> rows; // each row split on '|'
};

std::vector<std::string> split(const std::string& s) {
    std::vector<std::string> out;
    std::size_t b = 0;
    for (;;) {
        const auto e = s.find('|', b);
        out.push_back(s.substr(b, e == std::string::npos ? e : e - b));
        if (e == std::string::npos)
            return out;
        b = e + 1;
    }
}

Parsed parse(const std::string& text, std::size_t max_rows = kMaxRows) {
    Parsed p;
    yuzu::shared::RowByteBudget budget{max_rows, kMaxBytes};
    parse_authorized_keys(text, "acct", "authorized_keys", budget, p.kp);
    for (const auto& r : p.kp.rows)
        p.rows.push_back(split(r));
    return p;
}

std::string line(const std::string& type, const std::string& b64body, const std::string& comment = "c") {
    return type + " " + b64body + " " + comment + "\n";
}

// key row columns: key|acct|kind|type|fingerprint|bits|flags|options
constexpr std::size_t kType = 3, kFp = 4, kBits = 5, kFlags = 6, kOpts = 7;

void expect_one_key(const Parsed& p, const std::string& type, const std::string& fp, const std::string& bits,
                    const std::string& flags = "-", const std::string& opts = "-") {
    REQUIRE(p.rows.size() == 1);
    CHECK(p.kp.malformed == 0);
    CHECK(p.rows[0][kType] == type);
    CHECK(p.rows[0][kFp] == fp);
    CHECK(p.rows[0][kBits] == bits);
    CHECK(p.rows[0][kFlags] == flags);
    CHECK(p.rows[0][kOpts] == opts);
}

